CREATE TABLE `bookings` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `reference_code` varchar(32) NOT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `customer_name` varchar(120) NOT NULL,
  `customer_email` varchar(254) NOT NULL,
  `customer_phone` varchar(30) DEFAULT NULL,
  `student_id` varchar(50) DEFAULT NULL,
  `parent_phone_number` varchar(30) DEFAULT NULL,
  `parent_email_address` varchar(254) DEFAULT NULL,
  `dorm_id` bigint(20) UNSIGNED DEFAULT NULL,
  `service_name` varchar(120) NOT NULL,
  `booking_type` varchar(40) DEFAULT 'summer_storage',
  `pickup_date` date DEFAULT NULL,
  `pickup_time` time DEFAULT NULL,
  `pickup_location` varchar(160) DEFAULT NULL,
  `room_number` varchar(30) DEFAULT NULL,
  `dropoff_date` date DEFAULT NULL,
  `dropoff_time` time DEFAULT NULL,
  `dropoff_location` varchar(160) DEFAULT NULL,
  `dropoff_room_number` varchar(30) DEFAULT NULL,
  `pickup_status` varchar(30) DEFAULT 'unscheduled',
  `dropoff_status` varchar(30) DEFAULT 'unscheduled',
  `status` varchar(30) NOT NULL DEFAULT 'pending',
  `payment_status` varchar(30) NOT NULL DEFAULT 'unpaid',
  `subtotal` decimal(10,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `service_fee_percent` decimal(5,2) DEFAULT 0.00,
  `service_fee_amount` decimal(10,2) DEFAULT 0.00,
  `total_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `admin_notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `ordernumber` varchar(20) DEFAULT NULL,
  `card_holder_name` varchar(100) DEFAULT NULL,
  `booking_date` date DEFAULT NULL,
  `base_price` decimal(10,2) DEFAULT 0.00,
  `additional_box_quantity` int(10) UNSIGNED DEFAULT 0,
  `additional_box_amount` decimal(10,2) DEFAULT 0.00,
  `addtl_box_total_amount` decimal(10,2) DEFAULT 0.00,
  `study_abroad_additional_storage_price` decimal(10,2) DEFAULT 0.00,
  `is_study_abroad` tinyint(1) DEFAULT 0,
  `is_summer_school` tinyint(1) DEFAULT 0,
  `summer_school_fee` decimal(10,2) DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `row_in_warehouse` int(10) DEFAULT NULL,
  `terms_snapshot` mediumtext DEFAULT NULL,
  `terms_accepted_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

